//! Core geometric primitives, ported from `Clipper2Lib`'s `clipper.core.h`.
//!
//! `Point64` is the integer point type the library works with internally;
//! `PointD` is its floating point counterpart. `Rect64` is the axis aligned
//! bounding box used for clipping envelopes.

use std::fmt;
use std::ops::{Add, Mul, Neg, Sub};

/// An integer (64 bit) point, equivalent to `Clipper2Lib::Point64`.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub struct Point64 {
    pub x: i64,
    pub y: i64,
}

impl Point64 {
    /// `Point64(x, y)`
    pub const fn new(x: i64, y: i64) -> Self {
        Point64 { x, y }
    }

    /// `Point64(pt, scale)` — scales an existing point, rounding half away
    /// from zero the same way Clipper2's `std::llround` based ctor does.
    pub fn scaled(pt: Point64, scale: f64) -> Self {
        Point64 {
            x: round_half_away(pt.x as f64 * scale),
            y: round_half_away(pt.y as f64 * scale),
        }
    }

    pub fn to_pointd(self) -> PointD {
        PointD::new(self.x as f64, self.y as f64)
    }
}

impl Add for Point64 {
    type Output = Point64;
    fn add(self, rhs: Point64) -> Point64 {
        Point64::new(self.x + rhs.x, self.y + rhs.y)
    }
}

impl Sub for Point64 {
    type Output = Point64;
    fn sub(self, rhs: Point64) -> Point64 {
        Point64::new(self.x - rhs.x, self.y - rhs.y)
    }
}

impl Neg for Point64 {
    type Output = Point64;
    fn neg(self) -> Point64 {
        Point64::new(-self.x, -self.y)
    }
}

impl Mul<i64> for Point64 {
    type Output = Point64;
    fn mul(self, rhs: i64) -> Point64 {
        Point64::new(self.x * rhs, self.y * rhs)
    }
}

/// `operator<<` for `Point64` prints `x,y ` (trailing space), as Clipper2 does.
impl fmt::Display for Point64 {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{},{} ", self.x, self.y)
    }
}

impl From<(i64, i64)> for Point64 {
    fn from((x, y): (i64, i64)) -> Self {
        Point64::new(x, y)
    }
}

/// A double precision point, equivalent to `Clipper2Lib::PointD`.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct PointD {
    pub x: f64,
    pub y: f64,
}

impl PointD {
    pub const fn new(x: f64, y: f64) -> Self {
        PointD { x, y }
    }

    pub fn to_point64(self) -> Point64 {
        Point64::new(round_half_away(self.x), round_half_away(self.y))
    }
}

impl Add for PointD {
    type Output = PointD;
    fn add(self, rhs: PointD) -> PointD {
        PointD::new(self.x + rhs.x, self.y + rhs.y)
    }
}

impl Sub for PointD {
    type Output = PointD;
    fn sub(self, rhs: PointD) -> PointD {
        PointD::new(self.x - rhs.x, self.y - rhs.y)
    }
}

/// `operator<<` for `PointD` prints with the default `std::ostream` precision
/// (6 significant digits), followed by a trailing space.
impl fmt::Display for PointD {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{},{} ", default_ostream(self.x), default_ostream(self.y))
    }
}

impl From<(f64, f64)> for PointD {
    fn from((x, y): (f64, f64)) -> Self {
        PointD::new(x, y)
    }
}

/// An axis aligned rectangle, equivalent to `Clipper2Lib::Rect64`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Rect64 {
    pub left: i64,
    pub top: i64,
    pub right: i64,
    pub bottom: i64,
}

impl Rect64 {
    pub const fn new(left: i64, top: i64, right: i64, bottom: i64) -> Self {
        Rect64 {
            left,
            top,
            right,
            bottom,
        }
    }

    /// The "invalid" rect Clipper2 uses as a seed when accumulating bounds.
    pub const fn invalid() -> Self {
        Rect64::new(i64::MAX, i64::MAX, i64::MIN, i64::MIN)
    }

    pub fn width(&self) -> i64 {
        self.right - self.left
    }

    pub fn height(&self) -> i64 {
        self.bottom - self.top
    }

    pub fn is_empty(&self) -> bool {
        self.bottom <= self.top || self.right <= self.left
    }

    pub fn midpoint(&self) -> Point64 {
        Point64::new((self.left + self.right) / 2, (self.top + self.bottom) / 2)
    }

    pub fn contains(&self, pt: Point64) -> bool {
        pt.x > self.left && pt.x < self.right && pt.y > self.top && pt.y < self.bottom
    }
}

impl Default for Rect64 {
    fn default() -> Self {
        Rect64::new(0, 0, 0, 0)
    }
}

/// `(pt2 - pt1) x (pt3 - pt2)` — the sign tells the turn direction.
pub fn cross_product(pt1: Point64, pt2: Point64, pt3: Point64) -> f64 {
    ((pt2.x - pt1.x) as f64) * ((pt3.y - pt2.y) as f64)
        - ((pt2.y - pt1.y) as f64) * ((pt3.x - pt2.x) as f64)
}

pub fn dot_product(pt1: Point64, pt2: Point64, pt3: Point64) -> f64 {
    ((pt2.x - pt1.x) as f64) * ((pt3.x - pt2.x) as f64)
        + ((pt2.y - pt1.y) as f64) * ((pt3.y - pt2.y) as f64)
}

pub fn distance_sqr(pt1: Point64, pt2: Point64) -> f64 {
    let dx = (pt1.x - pt2.x) as f64;
    let dy = (pt1.y - pt2.y) as f64;
    dx * dx + dy * dy
}

pub fn distance(pt1: Point64, pt2: Point64) -> f64 {
    distance_sqr(pt1, pt2).sqrt()
}

/// C's `llround`: ties round away from zero (Rust's `f64::round` matches).
pub(crate) fn round_half_away(value: f64) -> i64 {
    value.round() as i64
}

/// Mimics the default `std::ostream` double formatting: 6 significant digits
/// with trailing zeros (and a trailing '.') removed.
pub(crate) fn default_ostream(value: f64) -> String {
    if !value.is_finite() {
        return if value.is_nan() {
            "nan".to_string()
        } else if value > 0.0 {
            "inf".to_string()
        } else {
            "-inf".to_string()
        };
    }

    let exp = if value == 0.0 {
        0
    } else {
        value.abs().log10().floor() as i32
    };

    // %g switches to scientific notation outside [1e-4, 1e6).
    if exp < -4 || exp >= 6 {
        let s = format!("{:e}", value);
        let (mantissa, e) = s.split_once('e').unwrap_or((s.as_str(), "0"));
        let mantissa: f64 = mantissa.parse().unwrap_or(0.0);
        let mantissa = trim_zeros(&format!("{:.*}", 5, mantissa));
        let e: i32 = e.parse().unwrap_or(0);
        format!("{}e{}{:02}", mantissa, if e < 0 { '-' } else { '+' }, e.abs())
    } else {
        let decimals = (5 - exp).max(0) as usize;
        trim_zeros(&format!("{:.*}", decimals, value))
    }
}

fn trim_zeros(s: &str) -> String {
    if !s.contains('.') {
        return s.to_string();
    }
    let s = s.trim_end_matches('0');
    s.trim_end_matches('.').to_string()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn point_arithmetic() {
        let a = Point64::new(3, 4);
        let b = Point64::new(1, 2);
        assert_eq!(a + b, Point64::new(4, 6));
        assert_eq!(a - b, Point64::new(2, 2));
        assert_eq!(-a, Point64::new(-3, -4));
        assert_eq!(a * 2, Point64::new(6, 8));
    }

    #[test]
    fn point_display_has_trailing_space() {
        assert_eq!(Point64::new(0, 0).to_string(), "0,0 ");
        assert_eq!(Point64::new(-1, 100).to_string(), "-1,100 ");
    }

    #[test]
    fn distances() {
        assert_eq!(distance(Point64::new(0, 0), Point64::new(3, 4)), 5.0);
        assert_eq!(distance_sqr(Point64::new(0, 0), Point64::new(3, 4)), 25.0);
    }

    #[test]
    fn cross_and_dot() {
        let (a, b, c) = (
            Point64::new(0, 0),
            Point64::new(100, 0),
            Point64::new(100, 100),
        );
        assert!(cross_product(a, b, c) > 0.0);
        assert_eq!(dot_product(a, b, c), 0.0);
    }

    #[test]
    fn rect_metrics() {
        let r = Rect64::new(0, 0, 100, 100);
        assert_eq!(r.width(), 100);
        assert_eq!(r.height(), 100);
        assert!(!r.is_empty());
        assert!(Rect64::invalid().is_empty());
        assert_eq!(r.midpoint(), Point64::new(50, 50));
        assert!(r.contains(Point64::new(50, 50)));
        assert!(!r.contains(Point64::new(0, 0)));
    }

    #[test]
    fn ostream_formatting() {
        assert_eq!(default_ostream(1.0), "1");
        assert_eq!(default_ostream(0.5), "0.5");
        assert_eq!(default_ostream(1.0 / 3.0), "0.333333");
    }
}

