//! via `path64![..]`) carries over, while `Deref` to a slice keeps the usual
//! Rust conveniences (`len`, iteration, indexing, slicing).

use std::fmt;
use std::iter::FromIterator;
use std::ops::{Deref, DerefMut, Index, IndexMut};

use super::core::{cross_product, Point64, Rect64};

